 "decisions": [
  {
   "title": "Transaction boundary of the transfer",
   "context": "The legacy opens a SqlTransaction after the same-account check and commits after inserting the transfer. Four validations roll it back.",
   "decision": "RealizarTransferencia runs in one transaction opened where the legacy begins it. A business error rolls back everything and rejects with its code. The same-account check happens before any database access, as in the legacy. No savepoints are needed, so no UnitOfWork port is declared.",
   "consequences": "A rejected transfer leaves CUENTAS and TRANSFERENCIAS unchanged. The balance and the number sequence are read and written in the same transaction."
  },
  {
   "title": "Commission calculation is pure domain logic",
   "context": "ComisionService.Calcular has no I/O and is called by the transfer handler.",
   "decision": "The calculation is a domain function (CalcularComision) with no port. It is exposed as its own use case and reused by RealizarTransferencia. Rounding is half away from zero, the cap is applied before the INM surcharge, and the surcharge is not capped.",
   "consequences": "The commission is identical in both places. A change to the commission rules is made in one place."
  },
  {
   "title": "Redirect replaced by a response",
   "context": "After the commit the page sets lblComision and lblMensaje and then redirects to Comprobante.aspx?numero=n, so the user never sees those labels.",
   "decision": "The service returns numero, comision and mensaje. The client navigates to GET /transferencias/{numero}/comprobante. No server-side redirect.",
   "consequences": "The result of the transfer is available to the caller. The receipt is a separate read-only use case."
  },
  {
   "title": "Sequential number kept as MAX+1",
   "context": "The legacy computes ISNULL(MAX(TRF_NUMERO),0)+1 inside the transaction, with no sequence object.",
   "decision": "The behaviour is kept so the numbering matches the golden master (first transfer is 1, then max plus one). The insert uses the primary key as the guard against duplicates.",
   "consequences": "Two concurrent transfers can compute the same number, and one of them fails on the key. This race exists in the legacy and is accepted. A database sequence could replace it later."
  },
  {
   "title": "Data moves to the target database",
   "context": "The legacy tables CUENTAS and TRANSFERENCIAS live in a SQL Server database that the rewritten application does not share.",
   "decision": "data_strategy is migration. The tables become cuentas and transferencias with the same precision (DECIMAL(13,2), DECIMAL(11,2), DECIMAL(7,2), VARCHAR(10), CHAR(1), CHAR(3)).",
   "consequences": "The data must be migrated before cutover. Monetary values keep their legacy scale of two decimals."
  },
  {
   "title": "UI validators and page plumbing are not translated",
   "context": "Transferencia.aspx has required, 10-digit and 1..10000 range validators that run in the browser or page, outside the handler. The page lifecycle, the connection string in Web.config and the redirect are framework plumbing.",
   "decision": "They are not translated into the domain. Input format checks belong to the API layer, outside the approved rules. The framework configuration replaces the connection string.",
   "consequences": "The use case enforces only the approved rules. Stricter input validation can be added at the controller without changing the domain."
  },
  {
   "title": "Missing transfer on the receipt is not an error",
   "context": "Comprobante leaves the amount blank when the number is unknown and shows no error.",
   "decision": "ConsultarComprobante returns the requested number and an empty amount in that case, with HTTP 200.",
   "consequences": "The behaviour is the same as the legacy. A client cannot tell a missing transfer from an error by status code."
  }
